<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:12px}h1{font-size:20px}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{border:1px solid #ccc;padding:8px}.right{text-align:right}</style></head><body><h1>Invoice Internet</h1><p><b>{{config('app.name')}}</b></p><p>Invoice: {{$invoice->invoice_number}}<br>Periode: {{$invoice->period}}<br>Jatuh Tempo: {{$invoice->due_date->format('d-m-Y')}}</p><p>Nama: {{$invoice->customer->name}}<br>ID: {{$invoice->customer->customer_code}}</p><table><tr><th>Deskripsi</th><th class="right">Jumlah</th></tr>@forelse($invoice->items as $item)<tr><td>{{$item->description}}</td><td class="right">Rp {{number_format($item->line_total,0,',','.')}}</td></tr>@empty<tr><td>{{$invoice->customer->package?->name}}</td><td class="right">Rp {{number_format($invoice->subtotal,0,',','.')}}</td></tr>@endforelse<tr><td>Diskon</td><td class="right">− Rp {{number_format($invoice->discount,0,',','.')}}</td></tr><tr><td>Denda</td><td class="right">Rp {{number_format($invoice->penalty,0,',','.')}}</td></tr>@if($invoice->tax_amount)<tr><td>PPN ({{$invoice->tax_rate}}%)</td><td class="right">Rp {{number_format($invoice->tax_amount,0,',','.')}}</td></tr>@endif<tr><th>Total</th><th class="right">Rp {{number_format($invoice->total,0,',','.')}}</th></tr></table></body></html>
